# UI language only; progress keys, states, version values and ZIP rules are unchanged.
$script:UpdateLanguages=@('ko','zh-CN','ja','en','ru','es','pt-BR','de','fr','it','pl','tr','zh-TW')
$script:UpdateLanguage='ko'
try{$v=[string](Get-ItemPropertyValue -Path 'HKCU:\Software\ModeSwitch' -Name Language -ErrorAction SilentlyContinue);foreach($c in $script:UpdateLanguages){if($v -ieq $c){$script:UpdateLanguage=$c;break}}}catch{}
$script:UpdateWords=@{}
# Row: ko, zh-CN, ja, en, ru, then the extra languages; a short row uses English for the rest.
function Add-UpdateWord{$row=@($args|ForEach-Object {[string]$_});while($row.Count -lt $script:UpdateLanguages.Count){$row+=$row[3]};$script:UpdateWords[$row[0]]=$row}
