function U([string]$Source,[object[]]$Values=@()){
 $row=$script:UpdateWords[$Source];$text=$Source
 if($null -ne $row){$at=[Array]::IndexOf($script:UpdateLanguages,$script:UpdateLanguage);if($at -lt 0){$at=0};$text=$row[$at]}
 if($Values.Count){return [string]::Format([Globalization.CultureInfo]::GetCultureInfo($script:UpdateLanguage),$text,$Values)}
 return $text
}
function Update-Error([Exception]$Exception){
 if($script:UpdateLanguage -eq 'ko'){return $Exception.Message}
 $cause=$Exception.GetBaseException();$at=[Array]::IndexOf($script:UpdateLanguages,$script:UpdateLanguage)
 foreach($row in $script:UpdateWords.Values){
  $pattern=[regex]::Escape($row[$at])
  foreach($placeholder in [regex]::Matches($row[$at],'\{\d+\}')){$pattern=$pattern.Replace([regex]::Escape($placeholder.Value),'.*')}
  if([regex]::IsMatch($cause.Message,('^'+$pattern+'$'))){return $cause.Message}
 }
 return $cause.GetType().Name+' (0x'+$cause.HResult.ToString('X8',[Globalization.CultureInfo]::InvariantCulture)+')'
}
